import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.DekDpfFM.js";const k=JSON.parse('{"title":"Installing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installing.md","filePath":"guide/installing.md","lastUpdated":1794312142000}'),n={name:"guide/installing.md"};function l(o,e,h,d,r,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h1><p>loom is a Python package with a C++ header library. It compiles your kernels on first use, so the machine needs a C++ compiler.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loom</span></span></code></pre></div><p>loom does not install a framework: it uses the ones you have, whichever they are. A call runs on the framework of the arrays it is given.</p><p>For CUDA kernels, the <code>cuda</code> extra brings a pinned nvcc (see below):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;loom[cuda]&#39;</span></span></code></pre></div><p>From a checkout, <code>pip install -e .</code> in the clone.</p><h2 id="the-compiler" tabindex="-1">The compiler <a class="header-anchor" href="#the-compiler" aria-label="Permalink to &quot;The compiler&quot;">​</a></h2><p>loom writes C++ and calls the compiler through <code>ninja</code>, which is installed with it. Two things to know:</p><ul><li><strong>The adjoint kernels need a recent compiler.</strong> They rely on C++ rules (P2280, unknown references in constant expressions) that Apple&#39;s clang does not implement and that recent clang releases only enable from C++23 on. On macOS, install a conda <code>clangxx</code> and point loom at it.</li><li><strong>For CUDA, the nvcc is pinned</strong> by the <code>cuda</code> extra (<code>&gt;=13.3,&lt;13.4</code>): the 13.4 frontend fails on loom&#39;s kernels, 13.3 works.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOOM_CXX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CONDA_PREFIX/bin/clang++</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOOM_CXXFLAGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=c++23</span></span></code></pre></div><p><code>loom-toolchain</code> says what this machine can compile for: the compiler and flags of each device, and what is missing.</p><p>When several frameworks are installed, the one used for values built <em>from nothing</em> (<code>RealTensor[ n ].zeros()</code>) is the first found among Jax, Torch, CuPy and NumPy; <code>LOOM_FRAMEWORK=torch</code> chooses another. A call given arrays always runs on theirs.</p><p>→ <a href="/loom/reference/environment">Environment variables</a></p><h2 id="check-that-it-works" tabindex="-1">Check that it works <a class="header-anchor" href="#check-that-it-works" aria-label="Permalink to &quot;Check that it works&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/diffusion</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diffusion.py</span></span></code></pre></div><p>The first run compiles two small kernels (a few seconds each, with <code>ninja</code> output on the way) and prints:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>40 diffusion steps on a 21x21 grid ( c = 0.2 )</span></span>
<span class="line"><span>  peak 1.0000 -&gt; 0.1988</span></span>
<span class="line"><span>  sum  25.1327 -&gt; 22.5915   ( it leaks through the boundary )</span></span></code></pre></div><p>A second run prints only those three lines: the compiled kernels are cached (<code>~/Library/Caches/loom</code> on macOS; see <code>LOOM_CACHE_DIR</code>).</p><div class="tip custom-block"><p class="custom-block-title">Where things are cached</p><p>Compiled kernels are keyed by a hash of their source and of what it was rendered with. Changing the C++ changes the key and recompiles; nothing else does.</p></div><h2 id="which-backend" tabindex="-1">Which backend <a class="header-anchor" href="#which-backend" aria-label="Permalink to &quot;Which backend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>framework</th><th>CPU</th><th>CUDA</th><th>gradient, <code>vmap</code></th></tr></thead><tbody><tr><td>Jax</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>Torch</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>CuPy</td><td>—</td><td>yes</td><td>no, forward only</td></tr><tr><td>NumPy</td><td>yes</td><td>—</td><td>no, forward only</td></tr></tbody></table><p>CUDA kernels are compiled by the nvcc of the <code>cuda</code> extra. The test suite runs on every line of this table.</p>`,24)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
